import { readFileSync, writeFileSync } from "node:fs";
const dir = new URL(".", import.meta.url).pathname;
const read = (f) => JSON.parse(readFileSync(dir + f, "utf8"));
const prep = read("prep.json");
const [sel, ed, ver] = prep.actorIds;
writeFileSync(dir + "request.json", JSON.stringify({
  schemaVersion: "1.0.0",
  mode: "direct",
  source: readFileSync(dir + "source.txt", "utf8"),
  subagentsAvailable: true,
  plan: {
    schemaVersion: "1.0.0",
    actorIds: prep.actorIds,
    providers: {
      selection: { kind: "agent", actorId: sel },
      editing: { kind: "agent", actorId: ed },
      verification: { kind: "agent", actorId: ver },
      finalization: { kind: "deterministic", entrypoint: "scripts/finalize.mjs" },
    },
  },
  manifest: prep.manifest,
  sourceUnitManifest: prep.units,
  glossaryMatchSet: null,
  selection: read("selection.json"),
  editing: read("editing.json"),
  verification: read("verification.json"),
  rubricDigest: prep.rubricDigest,
}));
